import type { ReactElement } from 'react';
import { Carousel, CarouselSlide, Card } from '@design-schema/react';

function slides(names: string[]): ReactElement[] {
  return names.map((name) => (
    <CarouselSlide key={name} label={name}>
      <Card heading={name}>{name}</Card>
    </CarouselSlide>
  ));
}

<Carousel label="Featured products">{slides(['Product 1', 'Product 2', 'Product 3', 'Product 4'])}</Carousel>

snippets.lit:
import '@design-schema/lit';
import { html, type TemplateResult } from 'lit';

const slides = (names: string[], body: (name: string) => string): TemplateResult[] =>
  names.map(
    (name) => html`
      <ds-carousel-slide label=${name}>
        <ds-card heading=${name} heading-level="3">${body(name)}</ds-card>
      </ds-carousel-slide>
    `,
  );

html`
  <ds-carousel label="Featured products">
    ${slides(['Product 1', 'Product 2', 'Product 3', 'Product 4'], () => 'A product worth a closer look.')}
  </ds-carousel>
`;

